      faqAiAssistantAnswer: "The project assistant can load project context, search project items, summarize status, suggest next steps, review budget signals, scrape product data for sourcing, and work with tasks, notes, contacts, payments, shopping lists, labor, surveys, moodboard sections, and project settings when the user enables change mode.",
