      faqAiAssistantQuestion: "What can the AI assistant actually do inside a project?",
      faqAiAttachmentsAnswer: "The assistant composer supports image and PDF attachments up to 32 MB, with up to 5 attachments in a message. Project PDFs can also be added to AI knowledge from the Files area so the assistant can search indexed document content during project conversations.",
