      faqAiAttachmentsQuestion: "Can the assistant work with uploaded files?",
      faqAiSafetyAnswer: "By default the assistant runs in read-only mode. Write tools are blocked until the user explicitly enables the setting that allows changes, and AI output still needs human review before it is used for client, budget, procurement, construction, legal, or compliance decisions.",
