      faqAiSafetyQuestion: "Can the assistant change project data automatically?",
      faqBody: "A practical overview of what the app covers, where each workflow lives, and how the pieces connect across the studio.",
      faqClientCollaborationAnswer: "The client portal and survey flows let clients review selected project information, respond to approvals, leave comments, and submit structured decisions. Client activity is surfaced back to the studio through project and organization notifications.",
      faqClientCollaborationCategory: "Client collaboration",
      faqClientCollaborationQuestion: "What can clients review without entering the full workspace?",
      faqCommercialAnswer: "Project delivery can include shopping totals, labor items, payment tracking, tax settings, estimates, invoice defaults, and budget reporting. These tools keep commercial decisions close to the design context instead of splitting them into separate spreadsheets.",
      faqCommercialCategory: "Commercial workflow",
      faqCommercialQuestion: "How does Myvibe handle budgets, labor, payments, and estimates?",
      faqEyebrow: "FAQ",
      faqFilesAnswer: "Files are stored inside the project with folders, breadcrumbs, previews, downloads, and deletion controls. Teams can upload images, videos, PDFs, DWG/DXF files, Office documents, and other project assets, then decide which files are visible in the client portal and which PDFs should be indexed for AI knowledge.",
      faqFilesCategory: "Files and exports",
      faqFilesQuestion: "What happens to project files and generated documents?",
      faqGeneratedDocumentsAnswer: "Myvibe supports exports and generated documents across shopping lists, labor documentation, company reports, project books, estimates, invoices, and client-facing survey file responses. These artifacts stay connected to the project instead of living only in external folders.",
      faqGeneratedDocumentsCategory: "Generated documents",
      faqGeneratedDocumentsQuestion: "Which workflows create documents or exports?",
      faqOrganizationAnswer: "The organization workspace brings together projects, team notifications, the global calendar, AI visualizations, product and survey libraries, team contacts, reports, tax settings, billing settings, team members, and subscription management.",
      faqOrganizationCategory: "Organization workspace",
      faqOrganizationQuestion: "What lives at the organization level?",
      faqPlanningAnswer: "Tasks, due dates, calendar views, project contacts, notes, and notifications are part of the same project record. The organization calendar rolls work up across projects, while each project keeps its own operational context.",
      faqPlanningCategory: "Planning",
      faqPlanningQuestion: "How are tasks, calendars, contacts, and notes connected?",
      faqPlansAnswer: "Core covers the operational project workspace without AI credits. Studio AI adds the assistant and visualizations for regular project work. Studio AI Plus adds a larger AI allowance for teams that use AI across many parallel projects.",
      faqPlansCategory: "Plans",
      faqPlansQuestion: "What is included in the paid plans?",
      faqProductScopeAnswer: "Myvibe is a workspace for architecture and interior studios that need project delivery, visual exploration, client collaboration, sourcing, files, reports, and AI support in one place. It connects the creative side of a project with the operational work that follows.",
      faqProductScopeCategory: "Product scope",
      faqProductScopeQuestion: "What is Myvibe built to manage?",
      faqProjectAnswer: "Each project has an overview, client portal, notifications, tasks, moodboard, notes, contacts, calendar, payments, surveys, files, shopping list, labor tracking, estimations, settings, and an AI assistant that works with the project context.",
      faqProjectCategory: "Project workspace",
      faqProjectQuestion: "What can a studio manage inside one project?",
      faqSourcingAnswer: "Shopping lists track products, finishes, suppliers, costs, statuses, sections, and project-specific decisions. Approved or reusable items can move into the product library so future projects can start from known products instead of rebuilding every selection from scratch.",
      faqSourcingCategory: "Sourcing",
      faqSourcingQuestion: "How do shopping lists and product libraries work together?",
