      faqBody: "Najczęstsze pytania o prowadzenie projektów, współpracę z klientem, dobór produktów, pliki i AI w jednym systemie pracowni.",
      faqAiAssistantAnswer: "Asystent projektu może wczytać kontekst projektu, szukać pozycji, podsumowywać status, sugerować kolejne kroki, analizować sygnały budżetowe, pobierać dane produktów do list zakupów i pracować z zadaniami, notatkami, kontaktami, płatnościami, robocizną, ankietami, sekcjami moodboardu oraz ustawieniami projektu, gdy użytkownik włączy tryb zmian.",
      faqAiAssistantCategory: "Asystent AI",
      faqAiAssistantQuestion: "Co asystent AI może zrobić w projekcie?",
      faqAiAttachmentsAnswer: "Kompozytor asystenta obsługuje obrazy i PDF-y do 32 MB oraz maksymalnie 5 załączników w wiadomości. PDF-y projektu można też dodać do wiedzy AI z obszaru Pliki, aby asystent mógł przeszukiwać zindeksowaną treść dokumentów w rozmowach projektowych.",
      faqAiAttachmentsCategory: "Załączniki AI",
      faqAiAttachmentsQuestion: "Czy asystent może pracować z przesłanymi plikami?",
      faqAiSafetyAnswer: "Domyślnie asystent działa w trybie tylko do odczytu. Narzędzia zapisu są blokowane, dopóki użytkownik wyraźnie nie włączy ustawienia pozwalającego na zmiany, a wyniki AI nadal wymagają ludzkiej weryfikacji przed użyciem w decyzjach klienckich, budżetowych, zakupowych, wykonawczych, prawnych lub compliance.",
      faqAiSafetyCategory: "Bezpieczeństwo AI",
      faqAiSafetyQuestion: "Czy asystent może automatycznie zmieniać dane projektu?",
      faqClientCollaborationAnswer: "Portal klienta i ankiety pozwalają klientom przeglądać wybrane informacje projektowe, odpowiadać na akceptacje, zostawiać komentarze i przesyłać uporządkowane decyzje. Aktywność klienta wraca do studia przez powiadomienia projektu i organizacji.",
      faqClientCollaborationCategory: "Współpraca z klientem",
      faqClientCollaborationQuestion: "Co klient może sprawdzić bez wchodzenia do wewnętrznego systemu pracowni?",
      faqCommercialAnswer: "Realizacja projektu może obejmować sumy zakupów, pozycje robocizny, śledzenie płatności, ustawienia podatkowe, kosztorysy, domyślne faktury i raportowanie budżetu. Te narzędzia trzymają decyzje komercyjne blisko kontekstu projektowego zamiast rozdzielać je do arkuszy.",
      faqCommercialCategory: "Budżet i realizacja",
      faqCommercialQuestion: "Jak Myvibe obsługuje budżety, robociznę, płatności i kosztorysy?",
      faqEyebrow: "FAQ",
      faqFilesAnswer: "Pliki są przechowywane w projekcie z folderami, okruszkami, podglądami, pobieraniem i kontrolą usuwania. Zespoły mogą przesyłać obrazy, wideo, PDF-y, pliki DWG/DXF, dokumenty Office i inne zasoby projektu, a potem decydować, które pliki są widoczne w portalu klienta i które PDF-y mają zostać zindeksowane dla wiedzy AI.",
      faqFilesCategory: "Pliki i eksporty",
      faqFilesQuestion: "Co dzieje się z plikami projektu i wygenerowanymi dokumentami?",
      faqGeneratedDocumentsAnswer: "Myvibe obsługuje eksporty i generowane dokumenty dla list zakupów, dokumentacji robocizny, raportów firmowych, ksiąg projektu, kosztorysów, faktur i odpowiedzi ankietowych z plikami dla klienta. Te artefakty zostają połączone z projektem zamiast żyć tylko w zewnętrznych folderach.",
      faqGeneratedDocumentsCategory: "Generowane dokumenty",
      faqGeneratedDocumentsQuestion: "Które obszary tworzą dokumenty lub eksporty?",
      faqOrganizationAnswer: "Poziom organizacji zbiera projekty, powiadomienia zespołu, globalny kalendarz, wizualizacje AI, biblioteki produktów i ankiet, kontakty zespołu, raporty, ustawienia podatków, ustawienia rozliczeń, członków zespołu oraz zarządzanie subskrypcją.",
      faqOrganizationCategory: "Organizacja",
      faqOrganizationQuestion: "Co znajduje się na poziomie organizacji?",
      faqPlanningAnswer: "Zadania, terminy, widoki kalendarza, kontakty projektu, notatki i powiadomienia są częścią tego samego rekordu projektu. Kalendarz organizacji zbiera pracę z wielu projektów, a każdy projekt zachowuje własny kontekst operacyjny.",
      faqPlanningCategory: "Planowanie",
      faqPlanningQuestion: "Jak połączone są zadania, kalendarze, kontakty i notatki?",
      faqPlansAnswer: "Core daje operacyjny workspace projektowy bez kredytów AI. Studio AI dodaje asystenta i wizualizacje do regularnej pracy projektowej. Studio AI Plus daje większą pulę AI dla zespołów pracujących z AI na wielu równoległych projektach.",
      faqPlansCategory: "Plany",
      faqPlansQuestion: "Co obejmują płatne plany?",
      faqProductScopeAnswer: "Myvibe to system dla pracowni architektury i wnętrz, które potrzebują prowadzenia projektów, eksploracji wizualnej, współpracy z klientem, doboru produktów, plików, raportów i wsparcia AI w jednym miejscu. Łączy kreatywną stronę projektu z pracą operacyjną, która po niej następuje.",
      faqProductScopeCategory: "Zakres produktu",
      faqProductScopeQuestion: "Do czego służy Myvibe?",
      faqProjectAnswer: "Każdy projekt ma przegląd, portal klienta, powiadomienia, zadania, moodboard, notatki, kontakty, kalendarz, płatności, ankiety, pliki, listę zakupów, śledzenie robocizny, kosztorysy, ustawienia i asystenta AI działającego z kontekstem projektu.",
      faqProjectCategory: "Projekt",
      faqProjectQuestion: "Co studio może zarządzać w jednym projekcie?",
      faqSourcingAnswer: "Listy zakupów śledzą produkty, wykończenia, dostawców, koszty, statusy, sekcje i decyzje specyficzne dla projektu. Zaakceptowane lub wielokrotnego użytku pozycje mogą trafić do biblioteki produktów, aby przyszłe projekty startowały od znanych wyborów.",
