      faqSourcingQuestion: "Jak współpracują listy zakupów i biblioteki produktów?",
      faqTeamAnswer: "Studio pracuje w organizacji z członkami zespołu, nawigacją zależną od roli, wspólnymi bibliotekami, ustawieniami organizacji i limitami subskrypcji. Klienci korzystają z portalu, ankiet i akceptacji zamiast trafiać do pełnego wewnętrznego systemu pracowni.",
      faqTeamCategory: "Zespół i dostęp",
