type I18nContextValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (
    namespace: string,
    key: string,
    values?: Record<string, string | number>,
  ) => string;
};

const I18nContext = createContext<I18nContextValue | null>(null);

const isLocale = (value: string | null | undefined): value is Locale =>
  locales.includes(value as Locale);

const getInitialLocale = (fallback: Locale): Locale => {
  if (typeof window === "undefined") {
    return fallback;
  }

  const storedLocale = window.localStorage.getItem(localeStorageKey);
  return isLocale(storedLocale) ? storedLocale : fallback;
};

export function I18nProvider({
  children,
  initialLocale = "en",
}: {
  children: ReactNode;
  initialLocale?: Locale;
}) {
  const [locale, setLocaleState] = useState<Locale>(initialLocale);

  useEffect(() => {
    setLocaleState(getInitialLocale(initialLocale));
  }, [initialLocale]);

  useEffect(() => {
    document.documentElement.lang = locale;
    window.localStorage.setItem(localeStorageKey, locale);
    document.cookie = `${localeStorageKey}=${locale};path=/;max-age=31536000;samesite=lax`;
  }, [locale]);

  const setLocale = useCallback((nextLocale: Locale) => {
    setLocaleState(nextLocale);
  }, []);

  const t = useCallback<I18nContextValue["t"]>(
    (namespace, key, values) => {
      const localeMessages = messages[locale] as Record<string, Record<string, string>>;
      const template =
        localeMessages[namespace]?.[key] ?? key;

      if (!values) {
        return template;
      }

      return template.replace(/\{(\w+)\}/g, (match, valueKey: string) =>
        Object.prototype.hasOwnProperty.call(values, valueKey)
          ? String(values[valueKey])
          : match,
      );
    },
    [locale],
  );

  const value = useMemo(
    () => ({
      locale,
      setLocale,
      t,
    }),
    [locale, setLocale, t],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const context = useContext(I18nContext);

  if (!context) {
    throw new Error("useI18n must be used within I18nProvider");
  }

  return context;
}
